class Counter:
    def __init__(self):
        self._value = 0
        self._alive = True

    def increment(self):
        if self._alive:
            self._value += 1

    def decrement(self):
        if self._alive and self._value > 0:
            self._value -= 1

    def get_value(self):
        return self._value

    def is_alive(self):
        return self._alive

    def close(self):
        self._alive = False
```

